AND AUTH.USER_ID = #{userId}
AND (PTL.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR PTL.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND PTL.PORTFOLIO_ID = #{initValue}

SELECT FIN.FINPROD_ABBR text, FIN.FINPROD_MARKET_ID id, FIN.FINPROD_ID object,
